                      </div>
                    )}

                    <div className="relative">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/60" />
                      <Input
                        placeholder="Cerca interessi..."
                        value={interestSearch}
                        onChange={(e) => setInterestSearch(e.target.value)}
                        className="pl-9 bg-white/15 backdrop-blur-md border-white/25 text-white placeholder:text-white/70"
                        data-testid="input-search-interests"
                      />
                    </div>

                    <div className="grid grid-cols-2 gap-2 max-h-[300px] overflow-y-auto">
                      {filteredInterests.map((item) => {
                        const isSelected = interests.includes(item);
                        return (
                          <button
                            key={item}
                            type="button"
                            onClick={() => toggleInterest(item)}
                            className={`flex items-center gap-2 p-3 rounded-lg text-left text-sm transition-all border backdrop-blur-md ${
                              isSelected
                                ? "border-primary bg-primary/20 text-white"
                                : "border-white/20 bg-white/10 text-white/80 hover:border-white/40"
                            }`}
                            data-testid={`button-interest-${slugify(item)}`}
                          >
                            <span className="flex-1 truncate">{item}</span>
                            {isSelected && <Check className="w-4 h-4 text-primary shrink-0" />}
                          </button>
                        );
                      })}
                    </div>
                </div>
              )}
            </motion.div>
          </AnimatePresence>

          <div className="flex items-center justify-between mt-6 gap-4">
            {step > 0 ? (
              <Button
                type="button"
                variant="outline"
                onClick={prevStep}
                className="gap-2"
                data-testid="button-prev-step"
              >
                <ArrowLeft className="w-4 h-4" />
                Indietro
              </Button>
            ) : (
              <div />
            )}

            <div className="flex items-center gap-2">
              {step >= 1 && step < TOTAL_STEPS - 1 && (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setStep(step + 1)}
                  className="text-white/60"
                  data-testid="button-skip-step"
                >
                  Salta
                </Button>
              )}

              {step < TOTAL_STEPS - 1 ? (
                <Button
                  type="button"
                  onClick={nextStep}
                  className="gap-2"
                  data-testid="button-next-step"
                >
                  Avanti
                  <ArrowRight className="w-4 h-4" />
                </Button>
              ) : (
                <div className="flex items-center gap-2">
                  {!existingProfile && (
                    <Button
                      type="submit"
                      variant="ghost"
                      disabled={isPending}
                      className="text-white/60"
                      onClick={() => { submitClickedRef.current = true; }}
                      data-testid="button-skip-save-profile"
                    >
                      Salta e Salva
                    </Button>
                  )}
                  <Button
                    type="submit"
                    disabled={isPending}
                    className="gap-2"
                    onClick={() => { submitClickedRef.current = true; }}
                    data-testid="button-save-profile"
                  >
                    {isPending ? (
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    ) : (
                      <Save className="w-4 h-4" />
                    )}
                    {existingProfile ? "Salva Modifiche" : "Crea Profilo"}
                  </Button>
                </div>
              )}
            </div>
          </div>
        </form>
      </Form>
      </div>
    </div>
  );
}

server/replit_integrations/image/routes..content:
import type { Express, Request, Response } from "express";
import { openai } from "./client";

export function registerImageRoutes(app: Express): void {
  app.post("/api/generate-image", async (req: Request, res: Response) => {
    try {
      const { prompt, size = "1024x1024" } = req.body;

      if (!prompt) {
        return res.status(400).json({ error: "Prompt is required" });
      }

      const response = await openai.images.generate({
        model: "gpt-image-1",
        prompt,
        n: 1,
        size: size as "1024x1024" | "512x512" | "256x256",
      });

      const imageData = response.data[0];
      res.json({
        url: imageData.url,
        b64_json: imageData.b64_json,
      });
    } catch (error) {
      console.error("Error generating image:", error);
      res.status(500).json({ error: "Failed to generate image" });
    }
  });
}

