            <div className="flex flex-col gap-3">
              <Link href="/register" onClick={() => exitGuestMode()}>
                <Button
                  className="w-full bg-gradient-to-r from-primary to-accent hover:opacity-90"
                  data-testid="button-guest-register"
                >
                  <UserPlus className="w-4 h-4 mr-2" />
                  Crea Account Gratuito
                </Button>
              </Link>

              <Link href="/login" onClick={() => exitGuestMode()}>
                <Button variant="outline" className="w-full" data-testid="button-guest-login">
                  Ho già un account
                </Button>
              </Link>

              <Button
                variant="ghost"
                className="text-muted-foreground"
                onClick={onClose}
                data-testid="button-guest-continue"
              >
                Continua a esplorare
              </Button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export function useGuestBlocker() {
  const { isGuest } = useGuest();
  const { isAuthenticated } = useAuth();
  const [showBlocker, setShowBlocker] = useState(false);
  const [blockerAction, setBlockerAction] = useState<string | undefined>();

  const blockIfGuest = (action?: string): boolean => {
    if (isGuest && !isAuthenticated) {
      setBlockerAction(action);
      setShowBlocker(true);
      return true;
    }
    return false;
  };

  return {
    showBlocker,
    blockerAction,
    setShowBlocker,
    blockIfGuest,
    GuestBlockerModal: () => (
      <GuestBlocker
        show={showBlocker}
        onClose={() => setShowBlocker(false)}
        action={blockerAction}
      />
    ),
  };
}

client/replit_integrations/audio/useVoic.content:
/**
 * React hook for voice recording using MediaRecorder API.
 * Records audio in WebM/Opus format for efficient streaming.
 */
import { useRef, useCallback, useState } from "react";

export type RecordingState = "idle" | "recording" | "stopped";

export function useVoiceRecorder() {
  const [state, setState] = useState<RecordingState>("idle");
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const startRecording = useCallback(async (): Promise<void> => {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const recorder = new MediaRecorder(stream, {
      mimeType: "audio/webm;codecs=opus",
    });

    mediaRecorderRef.current = recorder;
    chunksRef.current = [];

    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };

    recorder.start(100); // Collect chunks every 100ms
    setState("recording");
  }, []);

  const stopRecording = useCallback((): Promise<Blob> => {
    return new Promise((resolve) => {
      const recorder = mediaRecorderRef.current;
      if (!recorder || recorder.state !== "recording") {
        resolve(new Blob());
        return;
      }

      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: "audio/webm" });
        recorder.stream.getTracks().forEach((t) => t.stop());
        setState("stopped");
        resolve(blob);
      };

      recorder.stop();
    });
  }, []);

  return { state, startRecording, stopRecording };
}

